 q.options IS NULL) = 5 AND (SELECT COUNT(*) FROM questions q WHERE q.id LIKE 'q_eng_s1_%' AND q.question_type = 'structured' AND q.options IS NULL) = 3 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN questions q ON q.id = sp.question_id WHERE q.id LIKE 'q_eng_s1_%') = 9 AND (SELECT COUNT(*) FROM question_content_releases WHERE batch_id = 'wassce-english-sprint1-001') = 48 THEN 1 ELSE 0 END;
